if($_SERVER['REQUEST_METHOD']==='POST'&&($_POST['action']??'save_profile')==='save_profile'){csrf_check();$d=[];foreach(['nom_laboratoire','nom_gerant','telephone','email','adresse','ville','description'] as $f)$d[$f]=trim((string)($_POST[$f]??''));$d['site_web']=trim((string)($_POST['site_web']??''));$d['instagram']=trim((string)($_POST['instagram']??''));$selected=array_values(array_unique(array_filter(array_map('intval',(array)($_POST['services']??[])),fn($v)=>$v>0)));$lab=array_merge($lab,$d);try{foreach(['nom_laboratoire','nom_gerant','telephone','email','adresse','ville','description'] as $f)if($d[$f]==='')throw new RuntimeException('Tous les champs obligatoires sont requis.');if(!filter_var($d['email'],FILTER_VALIDATE_EMAIL))throw new RuntimeException('Adresse e-mail invalide.');if($d['site_web']!==''&&!filter_var($d['site_web'],FILTER_VALIDATE_URL))throw new RuntimeException('Site web invalide.');if(!$selected)throw new RuntimeException('Choisissez au moins un service.');$q=$pdo->prepare("SELECT `$labIdColumn` FROM laboratoire WHERE email=? AND `$labIdColumn`<>?");$q->execute([$d['email'],$id]);if($q->fetch())throw new RuntimeException('Cet e-mail est déjà utilisé.');$q=$pdo->prepare("SELECT COUNT(*) FROM service WHERE `$serviceIdColumn`=?");foreach($selected as $sid){$q->execute([$sid]);if((int)$q->fetchColumn()!==1)throw new RuntimeException('Service invalide.');}$pdo->beginTransaction();$q=$pdo->prepare("UPDATE laboratoire SET nom_laboratoire=?,nom_gerant=?,telephone=?,email=?,adresse=?,ville=?,site_web=?,instagram=?,description=? WHERE `$labIdColumn`=?");$q->execute([$d['nom_laboratoire'],$d['nom_gerant'],$d['telephone'],$d['email'],$d['adresse'],$d['ville'],$d['site_web']?:null,$d['instagram']?:null,$d['description'],$id]);$pdo->prepare('DELETE FROM laboratoire_service WHERE laboratoire_id=?')->execute([$id]);$q=$pdo->prepare('INSERT INTO laboratoire_service(laboratoire_id,service_id) VALUES(?,?)');foreach($selected as $sid)$q->execute([$id,$sid]);$pdo->commit();$_SESSION['nom_laboratoire']=$d['nom_laboratoire'];$success='Profil mis à jour.';}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error=$e instanceof RuntimeException?$e->getMessage():'Mise à jour impossible.';}}
$services=$pdo->query("SELECT `$serviceIdColumn` id,`$serviceNameColumn` nom FROM service ORDER BY `$serviceNameColumn`")->fetchAll();if(!isset($selected)){$q=$pdo->prepare('SELECT service_id FROM laboratoire_service WHERE laboratoire_id=?');$q->execute([$id]);$selected=array_map('intval',array_column($q->fetchAll(),'service_id'));}
